$now=(new \DateTimeImmutable('now',new \DateTimeZone('Europe/Rome')))->format('Y-m-d H:i:s');
$decisions=['granted'=>'Concesso','denied'=>'Negato','revoked'=>'Revocato','acknowledged'=>'Presa visione'];
