<style>
:root{color-scheme:light;--ink:#193345;--muted:#576c78;--line:#dce5e9;--brand:#086f75}*{box-sizing:border-box}body{margin:0;background:#f3f6f8;color:var(--ink);font:15px/1.55 system-ui,sans-serif}header{background:#fff;border-bottom:1px solid var(--line);padding:25px max(24px,calc((100% - 1160px)/2))}main{max-width:1208px;margin:auto;padding:24px}h1{font-size:28px;margin:8px 0}h2{font-size:22px;margin:0 0 16px}h3{font-size:17px}a{color:var(--brand)}nav{display:flex;gap:24px;flex-wrap:wrap;margin-top:22px}.muted,small{color:var(--muted)}.card{background:#fff;border:1px solid var(--line);border-radius:12px;padding:24px;margin-bottom:20px;scroll-margin-top:20px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.full{grid-column:1/-1}label{display:block;font-weight:600}input,select,textarea{width:100%;border:1px solid #afc2ca;border-radius:6px;padding:10px;font:inherit;color:var(--ink);background:#fff;margin:6px 0 12px}textarea{min-height:110px;resize:vertical}button,.button{display:inline-block;border:0;border-radius:6px;background:var(--brand);color:white;padding:10px 16px;font:600 14px system-ui;text-decoration:none;cursor:pointer}button:hover,.button:hover{background:#05565b}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #e69f35;outline-offset:3px}.secondary{background:#e8f2f3;color:#145b61}.tag{display:inline-block;background:#edf2f6;padding:4px 10px;border-radius:14px;font-size:12px}.notice{background:#e5f4ef;border-left:4px solid #218665;padding:14px;margin:16px 0}.entry{border-top:1px solid var(--line);padding:20px 0}.entry:first-of-type{border-top:0}.entry p,.text{white-space:pre-wrap;overflow-wrap:anywhere}.actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.actions form{margin:0}summary{cursor:pointer;font-weight:600;padding:12px 0}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid var(--line);