<article class="entry"><span class="tag"><?= esc($states[$entry['state']] ?? $entry['state']) ?></span> <small><?= esc($entry['occurred_at']) ?> · #<?= (int)$entry['id'] ?> · revisione <?= (int)$entry['revision'] ?></small>
<h3><?= esc($entry['content']['title']) ?></h3><div class="help"><?= esc(ClinicalRecordService::KINDS[$entry['kind']] ?? $entry['kind']) ?> · Autore #<?= (int)$entry['author_user_id'] ?><?php if($entry['previous_entry_id']): ?> · Correzione del documento #<?= (int)$entry['previous_entry_id'] ?><?php endif ?></div>
<p><?= esc($entry['content']['body']) ?></p>
<?php foreach(['anamnesis'=>'Anamnesi','findings'=>'Esame / riscontri','diagnosis'=>'Diagnosi','therapy'=>'Terapia','follow_up'=>'Indicazioni e controlli'] as $key=>$label): if(empty($entry['content'][$key])) continue; ?><details><summary><?= esc($label) ?></summary><p><?= esc($entry['content'][$key]) ?></p></details><?php endforeach ?>
