<?php if($own && $entry['state']==='draft'): ?><a href="<?= $base.'?edit='.(int)$entry['id'].'#nuovo' ?>">Modifica bozza</a>
<?php if($chart['actor']['role']===1): ?><form method="post" action="<?= $base.'/documenti/'.(int)$entry['id'].'/finalizza' ?>"><?= csrf_field() ?><input type="hidden" name="revision" value="<?= (int)$entry['revision'] ?>"><button>Rendi definitivo</button></form><?php endif ?>
<?php elseif($own): ?><a href="<?= $base.'?revise='.(int)$entry['id'].'#nuovo' ?>">Crea correzione</a><?php endif ?>
