</article><?php endforeach ?>
<?php if($chart['total']>25): ?><nav aria-label="Pagine documenti"><?php if($chart['page']>1): ?><a href="<?= $base.'?page='.($chart['page']-1) ?>">← Precedenti</a><?php endif ?><span>Pagina <?= (int)$chart['page'] ?></span><?php if($chart['page']*25<$chart['total']): ?><a href="<?= $base.'?page='.($chart['page']+1) ?>">Successivi →</a><?php endif ?></nav><?php endif ?></section>
