<div class="grid"><label>Tipo<select name="kind"><?php foreach(ClinicalRecordService::KINDS as $key=>$label): if($chart['actor']['role']!==1 && $key!=='note') continue; ?><option value="<?= esc($key,'attr') ?>" <?= ($source['kind'] ?? '')===$key ? 'selected' : '' ?>><?= esc($label) ?></option><?php endforeach ?></select></label>
<label>Data e ora della prestazione (Italia)<input type="datetime-local" name="occurred_at" required value="<?= esc(str_replace(' ','T',substr($source['occurred_at'] ?? $now,0,16)),'attr') ?>"></label>
