<?php if($chart['actor']['role']===1): foreach(['anamnesis'=>'Anamnesi','findings'=>'Esame / riscontri','diagnosis'=>'Diagnosi','therapy'=>'Terapia','follow_up'=>'Indicazioni e controlli'] as $key=>$label): ?><label><?= esc($label) ?><textarea name="<?= esc($key,'attr') ?>" maxlength="20000"><?= esc($content[$key] ?? '') ?></textarea></label><?php endforeach; endif ?>
<label>Appuntamento collegato<select name="appointment_id"><option value="0">Nessun collegamento</option><?php foreach($chart['appointments'] as $appointment): ?><option value="<?= (int)$appointment['id_appuntamento'] ?>" <?= (int)($source['appointment_id'] ?? 0)===(int)$appointment['id_appuntamento'] ? 'selected' : '' ?>>#<?= (int)$appointment['id_appuntamento'] ?> · <?= esc(($appointment['data_slot'] ?? '').' '.($appointment['tipo_visita_label'] ?? $appointment['stato'])) ?></option><?php endforeach ?></select></label></div>
<button>Salva bozza</button> <?php if($source): ?><a href="<?= $base ?>#nuovo">Annulla modifica</a><?php endif ?><p class="help">Il documento resta modificabile finché non viene reso definitivo. Le correzioni successive conservano il documento precedente.</p></form></section>
<section class="card" id="prestazioni"><h2>Storico prestazioni<?= !empty($chart['fse_enabled']) ? ' e referti FSE' : '' ?></h2><div class="table-wrap"><table><thead><tr><th>Appuntamento</th><th>Prestazione</th><th>Stato</th></tr></thead><tbody>
<?php foreach($chart['appointments'] as $appointment): ?><tr><td>#<?= (int)$appointment['id_appuntamento'] ?> · <?= esc(($appointment['data_slot'] ?? '').' '.($appointment['ora_inizio'] ?? '')) ?></td><td><?= esc($appointment['tipo_visita_label'] ?? 'Prestazione') ?><?php if(trim((string)($appointment['motivo_visita'] ?? ''))!==''): ?><br><small><?= esc($appointment['motivo_visita']) ?></small><?php endif ?></td><td><?= esc($appointment['stato']) ?></td></tr><?php endforeach ?></tbody></table></div>
<?php if(!$chart['appointments']): ?><p class="muted">Nessuna prestazione collegata visibile.</p><?php endif ?>
<?php foreach($chart['fse_reports'] as $report): ?><p>Referto FSE #<?= (int)$report['id_fse_document'] ?> · <?= esc($report['document_type'].' · '.$report['service_start'].' · '.$report['local_state']) ?> · <a href="<?= site_url('cartella-clinica/pazienti/'.$patientId.'/referti-fse/'.(int)$report['id_fse_document']) ?>">Scarica PDF disponibile</a></p><?php endforeach ?>
<p class="help">Lo storico riporta gli stati registrati in agenda.<?php if (!empty($chart['fse_enabled'])): ?> I documenti FSE mantengono il proprio percorso di validazione e pubblicazione.<?php endif ?></p></section>
<?php endif ?>
