<?php foreach($chart['objects'] as $object): ?><p><a href="<?= $download($object['id']) ?>"><?= esc($object['name']) ?></a> <small>· <?= esc($object['created_at']) ?><?= $object['entry_id'] ? ' · documento #'.(int)$object['entry_id'] : '' ?></small></p><?php endforeach ?>
<details><summary>Aggiungi documento</summary><form method="post" enctype="multipart/form-data" action="<?= $base ?>/allegati"><?= csrf_field() ?>
