<details class="entry"><summary><?= esc($template['title'].' · versione '.$template['version']) ?> <span class="tag"><?= esc($head && (int)$head['template_id']===(int)$template['id'] ? ($decisions[$head['decision']] ?? $head['decision']) : 'Nessuna scelta attuale per questa versione') ?></span></summary>
<div class="text"><?= esc($template['content']) ?></div>
<form method="post" action="<?= $base ?>/consensi"><?= csrf_field() ?><input name="template_id" type="hidden" value="<?= (int)$template['id'] ?>"><input type="hidden" name="previous_id" value="<?= (int)($head['id'] ?? 0) ?>">
<div class="grid"><label>Scelta<select name="decision"><?php foreach($template['kind']==='privacy_notice' ? ['acknowledged'] : ['granted','denied','revoked'] as $decision): ?><option value="<?= $decision ?>"><?= esc($decisions[$decision]) ?></option><?php endforeach ?></select></label>
<label>Documento sottoscritto<select name="evidence_object_id"><option value="">Seleziona documento</option><?php foreach($chart['objects'] as $object): if($object['category']!=='consent') continue; ?><option value="<?= esc($object['id'],'attr') ?>"><?= esc($object['name']) ?></option><?php endforeach ?></select></label>
<label>Nome e cognome del dichiarante<input name="signer_name" maxlength="160" required></label><label>Qualità del dichiarante<input name="signer_capacity" placeholder="Paziente, genitore, tutore…" maxlength="160" required></label><label class="full">Annotazioni<textarea name="note" maxlength="2000"></textarea></label></div><button>Registra scelta</button></form></details><?php endforeach ?>
<details><summary>Storico completo dei consensi (<?= count($chart['consents']) ?>)</summary><?php foreach($chart['consents'] as $consent): ?><p><?= esc($consent['recorded_at'].' · '.(ClinicalRecordService::CONSENTS[$consent['kind']] ?? $consent['kind']).' · '.($decisions[$consent['decision']] ?? $consent['decision'])) ?><br><small>Modello #<?= (int)$consent['template_id'] ?> · <?= esc($consent['signer']['name'].' · '.$consent['signer']['capacity']) ?> · Operatore #<?= (int)$consent['recorded_by'] ?></small></p><?php endforeach ?></details>
<?php if($chart['manage_templates']): ?><details><summary>Pubblica un modello di consenso</summary><form method="post" action="<?= $base ?>/modelli"><?= csrf_field() ?><div class="grid"><label>Finalità<select name="kind"><?php foreach(ClinicalRecordService::CONSENTS as $key=>$label): ?><option value="<?= $key ?>"><?= esc($label) ?></option><?php endforeach ?></select></label><label>Versione<input name="version" maxlength="32" required></label><label class="full">Titolo<input name="title" maxlength="160" required></label><label class="full">Testo approvato dalla struttura<textarea name="content" maxlength="60000" required></textarea></label></div><button>Pubblica versione</button><p class="help">Il testo pubblicato resta invariato. Per aggiornarlo, pubblica una nuova versione.</p></form></details><?php endif ?>
